CREATE EXTENSION IF NOT EXISTS "pgcrypto";

CREATE TABLE IF NOT EXISTS public.bike_bookings (id bigint generated by default as identity primary key, created_at timestamp with time zone default timezone('utc'::text, now()) not null, booking_id text, customer_name text not null, phone text not null, email text, bike_model text, area text, service_type text);

CREATE TABLE IF NOT EXISTS public.bookings (id uuid primary key default gen_random_uuid(), created_at timestamp with time zone default timezone('utc'::text, now()) not null, job_id text, booking_code text, division text default '2W-PETROL', customer_name text not null, customer_phone text not null, customer_mobile text, customer_email text, vehicle_brand text, vehicle_model text, vehicle_reg text default 'Collected on Call', registration_no text default 'Collected on Call', vehicle_class text default 'Petrol Two-Wheeler (100cc-2500cc)', engine_cc text default '100cc-2500cc', service_package text, service_category text, area_name text, pincode text, pickup_fee numeric default 0, pickup_charge numeric default 0, customer_notes text, status text default 'Booking Confirmed', booking_status text default 'received');

CREATE TABLE IF NOT EXISTS public.job_cards (id uuid primary key default gen_random_uuid(), created_at timestamp with time zone default timezone('utc'::text, now()) not null, job_card_no text, booking_id text, customer_name text, customer_phone text, vehicle_model text, reg_number text, odometer_km numeric default 0, next_service_due_km numeric default 3000, next_service_due_date text, inspection_notes text, parts_changed text, total_amount numeric default 0, warranty_certificate_no text, warranty_status text default '30-Day Unconditional Workmanship Guarantee Active', dispatched_by text default 'Mr. Nitish Kumar (Manager & Lead Dispatcher, +91 8333084261)');

CREATE TABLE IF NOT EXISTS public.family_vehicles (id uuid primary key default gen_random_uuid(), created_at timestamp with time zone default timezone('utc'::text, now()) not null, customer_phone text not null, customer_name text, vehicle_brand text not null, vehicle_model text not null, reg_number text not null, vehicle_class text default 'Petrol Two-Wheeler (100cc-2500cc)', engine_cc text default '100cc-2500cc', odometer_km numeric default 0, last_service_date text, next_service_due_date text, next_service_due_km numeric default 3000, parts_changed_history text, warranty_status text default 'Active — 30-Day Workmanship Guarantee');

GRANT USAGE ON SCHEMA public TO anon, authenticated, public;
GRANT ALL ON ALL TABLES IN SCHEMA public TO anon, authenticated, public;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated, public;

ALTER TABLE public.bike_bookings ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public anonymous bike bookings insert" ON public.bike_bookings;
CREATE POLICY "Allow public anonymous bike bookings insert" ON public.bike_bookings FOR INSERT TO public, anon, authenticated WITH CHECK (true);
DROP POLICY IF EXISTS "Allow authenticated view bike bookings" ON public.bike_bookings;
CREATE POLICY "Allow authenticated view bike bookings" ON public.bike_bookings FOR SELECT TO public, anon, authenticated USING (true);
DROP POLICY IF EXISTS "Allow update bike bookings" ON public.bike_bookings;
CREATE POLICY "Allow update bike bookings" ON public.bike_bookings FOR UPDATE TO public, anon, authenticated USING (true) WITH CHECK (true);

ALTER TABLE public.bookings ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow all on bookings" ON public.bookings;
CREATE POLICY "Allow all on bookings" ON public.bookings FOR ALL TO public, anon, authenticated USING (true) WITH CHECK (true);

ALTER TABLE public.job_cards ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow all on job_cards" ON public.job_cards;
CREATE POLICY "Allow all on job_cards" ON public.job_cards FOR ALL TO public, anon, authenticated USING (true) WITH CHECK (true);

ALTER TABLE public.family_vehicles ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow all on family_vehicles" ON public.family_vehicles;
CREATE POLICY "Allow all on family_vehicles" ON public.family_vehicles FOR ALL TO public, anon, authenticated USING (true) WITH CHECK (true);

CREATE OR REPLACE FUNCTION public.create_express_booking(p_booking_id text, p_customer_name text, p_phone text, p_email text, p_bike_model text, p_area text, p_service_type text) RETURNS json LANGUAGE plpgsql SECURITY DEFINER AS $$ BEGIN INSERT INTO public.bike_bookings (booking_id, customer_name, phone, email, bike_model, area, service_type) VALUES (p_booking_id, p_customer_name, p_phone, p_email, p_bike_model, p_area, p_service_type); INSERT INTO public.bookings (job_id, booking_code, customer_name, customer_phone, customer_mobile, vehicle_model, service_package, service_category, area_name, pincode, status) VALUES (p_booking_id, p_booking_id, p_customer_name, p_phone, p_phone, p_bike_model, p_service_type, p_service_type, p_area, p_area, 'Booking Confirmed'); RETURN json_build_object('status', 'ok', 'booking_id', p_booking_id); END; $$;

GRANT EXECUTE ON FUNCTION public.create_express_booking(text, text, text, text, text, text, text) TO anon, authenticated, public;

NOTIFY pgrst, 'reload schema';
